  const state = createState(1);
  // Place ball just above a brick, moving down
  const brick = state.bricks[0]; // Top-left brick
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - BALL_R - 1;
  state.ball.vy = 100; // Moving DOWN
  state.ball.vx = 0;

  // Mock canvas context
  const ctx = {
    fillRect: () => {},
    arc: () => {},
    fill: () => {},
    beginPath: () => {},
    fillText: () => {},
  };

  frame(ctx, state);

  // Currently, this fails because frame() doesn't change vy
  // Expected: ball.vy should be negative (UP)
  assertEquals(Math.sign(state.ball.vy), -1, 'Ball should have bounced UP');
});

test('D2: Tunneling at high speed', () => {
  // Level 6: speed = 260 + 5 * 90 = 710. dt = 0.05. Jump = 35.5px.
  // Brick height = 20px.
  const state = createState(6);
  const brick = state.bricks[0];

  // Position ball such that in one step it would jump over the brick
  // Brick is at y = BRICK_TOP = 48. h = 20. Bottom = 68.
  // Ball r = 7.
  // Let's put ball at y = 40. vy = 710.
  // Next position: 40 + 710 * 0.05 = 40 + 35.5 = 75.5.
  // Ball top = 75.5 - 7 = 68.5.
  // It just barely missed the brick (bottom is 68).

  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = 40;
  state.ball.vy = 710;
  state.ball.vx = 0;

  // We need to simulate the loop: step() then frame()
  const ctx = { fillRect: () => {}, arc: () => {}, fill: () => {}, beginPath: () => {}, fillText: () => {} };

  // We only care if the brick is broken.
  // In the actual game, step() happens then frame()
  // We can't use step() because it handles walls/paddle.
  // Let's just simulate the movement and call frame().

  const dt = 0.05;
  state.ball.y += state.ball.vy * dt;

  frame(ctx, state);

  assertEquals(brick.alive, false, 'Brick should have been broken even with high speed');
});

